<?php use App\Core\Authorization; use App\Core\Csrf; $manage=Authorization::allows('academics.manage'); ?>
<style>.academics-page{font-size:.87rem}.academics-page .page-heading{margin-bottom:.8rem}.academics-page .page-heading h1{font-size:1.85rem;margin-bottom:.35rem}.academics-page .academic-forms{grid-template-columns:repeat(3,minmax(0,1fr));gap:.7rem}.academics-page .academic-forms .card{padding:.9rem}.academics-page .academic-forms .span-two{grid-column:1/-1}.academics-page .form-section h2{font-size:1rem;padding-bottom:.45rem;margin-bottom:.65rem}.academics-page .stack-form{gap:.62rem}.academics-page label{gap:.22rem}.academics-page input,.academics-page select,.academics-page textarea{padding:.52rem .62rem;border-radius:8px}.academics-page .grid{gap:.55rem}.academics-page .button{padding:.52rem .75rem}.academics-page .section-card{padding:1rem;margin-top:.7rem}.academics-page th,.academics-page td{padding:.65rem .72rem}.academics-page .reference-lists{margin-top:.7rem;gap:.7rem}.academics-page .reference-lists .form-section{padding:1rem}.academics-page #terms:target{outline:3px solid rgba(125,88,190,.2);box-shadow:0 14px 32px rgba(78,48,129,.14)}.academic-term{padding-left:.5rem;border-left:2px solid rgba(117,84,181,.22)}@media(max-width:1100px){.academics-page .academic-forms{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:800px){.academics-page .academic-forms{grid-template-columns:1fr}.academics-page .academic-forms .span-two{grid-column:auto}}</style>
<div class="academics-page">
<div class="page-heading"><div><p class="eyebrow">Administration</p><h1>Academic structure</h1><p>Configure school years, departments, grade levels, subjects, and sections.</p></div></div>
<?php if($manage):?><div class="academic-forms">
<section class="card form-section"><h2>Add school year</h2><form method="post" action="<?=e(url('/admin/academics/school-year'))?>" class="stack-form"><?=Csrf::field()?><label>Name<input required name="name" placeholder="2026–2027"></label><div class="grid two"><label>Starts<input required type="date" name="starts_on"></label><label>Ends<input required type="date" name="ends_on"></label></div><label class="inline-check"><input type="checkbox" name="is_active" value="1"> Make active</label><button class="button primary">Add school year</button></form></section>
<section class="card form-section" id="terms"><h2>Add academic term</h2><form method="post" action="<?=e(url('/admin/academics/term'))?>" class="stack-form"><?=Csrf::field()?><label>School year<select required name="school_year_id"><option value="">Select school year</option><?php foreach($schoolYears as $x):?><option value="<?=$x['id']?>"><?=e($x['name'])?></option><?php endforeach;?></select></label><div class="grid two"><label>Term name<input required name="name" placeholder="First Semester"></label><label>Display order<input required type="number" min="1" name="sequence_no" placeholder="1"></label><label>Starts<input required type="date" name="starts_on"></label><label>Ends<input required type="date" name="ends_on"></label></div><button class="button primary">Add term</button></form></section>
<section class="card form-section"><h2>Add department</h2><form method="post" action="<?=e(url('/admin/academics/department'))?>" class="stack-form"><?=Csrf::field()?><label>Code<input required name="code" placeholder="SCI"></label><label>Name<input required name="name" placeholder="Science Department"></label><button class="button primary">Add department</button></form></section>
<section class="card form-section"><h2>Add grade level</h2><form method="post" action="<?=e(url('/admin/academics/grade'))?>" class="stack-form"><?=Csrf::field()?><label>Code<input required name="code" placeholder="G7"></label><label>Name<input required name="name" placeholder="Grade 7"></label><label>Display order<input required type="number" min="1" name="sequence_no"></label><button class="button primary">Add grade</button></form></section>
<section class="card form-section"><h2>Add subject</h2><form method="post" action="<?=e(url('/admin/academics/subject'))?>" class="stack-form"><?=Csrf::field()?><label>Code<input required name="code" placeholder="MATH7"></label><label>Name<input required name="name" placeholder="Mathematics 7"></label><label>Description<input name="description"></label><button class="button primary">Add subject</button></form></section>
<section class="card form-section span-two"><h2>Add section</h2><form method="post" action="<?=e(url('/admin/academics/section'))?>" class="stack-form"><?=Csrf::field()?><div class="grid three"><label>School year<select required name="school_year_id"><option value="">Select</option><?php foreach($schoolYears as $x):?><option value="<?=$x['id']?>"><?=e($x['name'])?></option><?php endforeach;?></select></label><label>Grade level<select required name="grade_level_id"><option value="">Select</option><?php foreach($grades as $x):?><option value="<?=$x['id']?>"><?=e($x['name'])?></option><?php endforeach;?></select></label><label>Section name<input required name="name" placeholder="Rizal"></label><label>Adviser<select name="adviser_teacher_id"><option value="">Not assigned</option><?php foreach($teachers as $x):?><option value="<?=$x['id']?>"><?=e($x['last_name'].', '.$x['first_name'].' ('.$x['employee_no'].')')?></option><?php endforeach;?></select></label><label>Capacity<input type="number" min="1" name="capacity"></label><label>Room<input name="room"></label></div><button class="button primary">Add section</button></form></section></div><?php endif;?>
<?php if($manage):?><section class="card form-section section-card"><h2>Assign subject to teacher</h2><form method="post" action="<?=e(url('/admin/academics/assignment'))?>" class="stack-form"><?=Csrf::field()?><div class="grid three"><label>Teacher<select required name="teacher_id"><option value="">Select teacher</option><?php foreach($teachers as $x):?><option value="<?=$x['id']?>"><?=e($x['last_name'].', '.$x['first_name'].' ('.$x['employee_no'].')')?></option><?php endforeach;?></select></label><label>Section<select required name="section_id"><option value="">Select section</option><?php foreach($sections as $x):?><option value="<?=$x['id']?>"><?=e($x['school_year'].' · '.$x['grade_level'].' '.$x['name'])?></option><?php endforeach;?></select></label><label>Subject<select required name="subject_id"><option value="">Select subject</option><?php foreach($subjects as $x):?><option value="<?=$x['id']?>"><?=e($x['code'].' — '.$x['name'])?></option><?php endforeach;?></select></label><label>Term (optional)<select name="term_id"><option value="">Whole school year</option><?php foreach($terms as $x):?><option value="<?=$x['id']?>"><?=e($x['name'])?></option><?php endforeach;?></select></label><label>Schedule<input name="schedule_text" placeholder="Mon/Wed 9:00–10:00"></label><label>Room<input name="room" placeholder="Room 201"></label></div><label class="inline-check"><input type="checkbox" name="is_primary" value="1" checked> Primary teacher for this subject</label><button class="button primary">Save teaching assignment</button></form></section><?php endif;?>
<section class="card table-card section-card"><h2>Teaching assignments</h2><table><thead><tr><th>Teacher</th><th>Subject</th><th>Section</th><th>Schedule</th></tr></thead><tbody><?php foreach($assignments as $x):?><tr><td><strong><?=e($x['teacher_name'])?></strong><br><small><?=e($x['employee_no'])?></small></td><td><?=e($x['subject_code'].' — '.$x['subject_name'])?><?php if($x['is_primary']):?> <span class="badge">Primary</span><?php endif;?></td><td><?=e($x['school_year'].' · '.$x['grade_level'].' '.$x['section_name'])?><?php if($x['term_name']):?><br><small><?=e($x['term_name'])?></small><?php endif;?></td><td><?=e($x['schedule_text']?:'—')?><?php if($x['room']):?><br><small><?=e($x['room'])?></small><?php endif;?></td></tr><?php endforeach;?><?php if(!$assignments):?><tr><td colspan="4" class="empty">No subject assignments recorded yet.</td></tr><?php endif;?></tbody></table></section>
<section class="card table-card section-card"><h2>Sections</h2><table><thead><tr><th>School year</th><th>Grade and section</th><th>Adviser</th><th>Room</th></tr></thead><tbody><?php foreach($sections as $x):?><tr><td><?=e($x['school_year'])?></td><td><strong><?=e($x['grade_level'].' '.$x['name'])?></strong></td><td><?=e($x['adviser']?:'—')?></td><td><?=e($x['room']?:'—')?></td></tr><?php endforeach;?><?php if(!$sections):?><tr><td colspan="4" class="empty">No sections configured.</td></tr><?php endif;?></tbody></table></section>
<div class="grid three reference-lists"><section class="card form-section"><h2>School years &amp; terms</h2><?php foreach($schoolYears as $x):?><p><strong><?=e($x['name'])?></strong> <?=$x['is_active']?'<span class="badge">Active</span>':''?><br><small><?=e($x['starts_on'].' to '.$x['ends_on'])?></small></p><?php foreach($terms as $term):?><?php if((int)$term['school_year_id']===(int)$x['id']):?><p class="academic-term"><span class="badge"><?=e($term['sequence_no'])?></span> <strong><?=e($term['name'])?></strong><br><small><?=e($term['starts_on'].' to '.$term['ends_on'])?></small></p><?php endif;?><?php endforeach;?><?php endforeach;?></section><section class="card form-section"><h2>Departments</h2><?php foreach($departments as $x):?><p><strong><?=e($x['code'])?></strong> — <?=e($x['name'])?></p><?php endforeach;?></section><section class="card form-section"><h2>Grades and subjects</h2><?php foreach($grades as $x):?><span class="badge"><?=e($x['name'])?></span> <?php endforeach;?><hr><?php foreach($subjects as $x):?><p><strong><?=e($x['code'])?></strong> — <?=e($x['name'])?></p><?php endforeach;?></section></div>
</div>
